import java.io.IOException;
import java.io.InputStream;
import java.lang.annotation.Annotation;
import java.lang.reflect.Type;

import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;
import javax.ws.rs.ext.MessageBodyReader;
import javax.ws.rs.ext.MessageBodyWriter;

import org.apache.abdera.Abdera;
import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;

/**
 * Secure implementation of the Atom provider.
 *
 * The {@code readFrom} method now creates a fresh {@link Parser} instance for each
 * request and configures it *before* any parsing occurs.  All entity resolution
 * features are explicitly disabled to eliminate the XML External Entity (XXE)
 * attack surface.  The parser is no longer shared across threads, removing the
 * need for synchronization and guaranteeing that the hardened configuration
 * is applied consistently.
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    private static final Abdera ATOM_ENGINE = new Abdera();
    private boolean autodetectCharset;

    // ----------------------------------------------------------------------
    //  Secure readFrom implementation
    // ----------------------------------------------------------------------
    @Override
    public T readFrom(Class<T> clazz,
                      Type type,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        // Create a *new* parser for this request – no shared mutable state.
        Parser parser = ATOM_ENGINE.getParser();

        // Obtain the default options (may be null) and ensure we have a mutable
        // instance to work with.
        ParserOptions options = parser.getDefaultParserOptions();
        if (options == null) {
            options = new ParserOptions();
        }

        // ------------------------------------------------------------------
        // Harden the parser against XXE
        // ------------------------------------------------------------------
        // 1. Disable automatic charset detection if the caller requested it.
        options.setAutodetectCharset(autodetectCharset);

        // 2. Turn off entity resolution – this prevents external DTDs and
        //    general entities from being fetched.
        options.setResolveEntities(false);

        // 3. Explicitly disable expansion of entity references (available in
        //    newer Abdera versions).  If the method does not exist we simply
        //    ignore the call – the previous step already blocks external
        //    entities.
        try {
            options.setExpandEntityReferences(false);
        } catch (NoSuchMethodError | IllegalArgumentException ignored) {
            // Method not present in older Abdera releases – safe to ignore.
        }

        // Apply the hardened options to the parser *before* parsing.
        parser.setParserOptions(options);

        // ------------------------------------------------------------------
        // Parse the input safely.
        // ------------------------------------------------------------------
        Document<T> doc;
        try {
            doc = parser.parse(entityStream);
        } finally {
            // Ensure the stream is closed to avoid resource leaks.
            try {
                entityStream.close();
            } catch (IOException ignored) {
                // Swallow – the caller already expects an IOException.
            }
        }

        // Return the root element of the parsed Atom document.
        return doc.getRoot();
    }

    // ----------------------------------------------------------------------
    //  Other abstract/provider methods would follow...
    // ----------------------------------------------------------------------
}
