static public File allocateFile(File dir, String name) {
    if (dir == null) {
        throw new IllegalArgumentException("Target directory must not be null");
    }
    if (name == null) {
        throw new IllegalArgumentException("File name must not be null");
    }

    // Remove any query string part
    int q = name.indexOf('?');
    if (q > 0) {
        name = name.substring(0, q);
    }

    // Resolve the name against the target directory and normalize the path
    java.nio.file.Path targetDir = dir.toPath().toAbsolutePath().normalize();
    java.nio.file.Path candidate = targetDir.resolve(name).normalize();

    // Ensure the resulting path is still inside the intended directory
    if (!candidate.startsWith(targetDir)) {
        throw new IllegalArgumentException("Invalid file name, path traversal detected: " + name);
    }

    // Use only the file name part for further duplicate handling
    String fileName = candidate.getFileName().toString();

    // Split into prefix and suffix
    int dot = fileName.lastIndexOf('.');
    String prefix = (dot < 0) ? fileName : fileName.substring(0, dot);
    String suffix = (dot < 0) ? "" : fileName.substring(dot);

    java.nio.file.Path result = targetDir.resolve(fileName);
    int index = 2;
    while (java.nio.file.Files.exists(result)) {
        String newName = prefix + "-" + index++ + suffix;
        result = targetDir.resolve(newName);
    }

    // Ensure parent directories exist
    java.nio.file.Files.createDirectories(result.getParent());

    return result.toFile();
}
