import javax.ws.rs.ext.RuntimeDelegate;

/**
 * Header delegate for {@code MediaType}.  The {@code isValid} method validates
 * the {@code major} and {@code subtype} tokens according to RFC 7230.
 * Only characters that are permitted in a HTTP token are accepted.
 * This prevents CR/LF injection and other illegal characters from being
 * used in HTTP header values.
 */
public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate {

    // -----------------------------------------------------------------------
    //  Token validation (RFC 7230, section 3.2.6)
    // -----------------------------------------------------------------------
    // token = 1*tchar
    // tchar = "!" / "#" / "$" / "%" / "&" / "'" / "*"
    //       / "+" / "-" / "." / "^" / "_" / "`" / "|" / "~"
    //       / DIGIT / ALPHA
    // No CTL characters (0‑31, 127) and no whitespace are allowed.
    // -----------------------------------------------------------------------
    private static final boolean[] TOKEN_CHAR = new boolean[128];

    static {
        // initialise the lookup table with the allowed characters
        String allowed = "!#$%&'*+-.^_`|~"
                + "0123456789"
                + "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
                + "abcdefghijklmnopqrstuvwxyz";
        for (char c : allowed.toCharArray()) {
            TOKEN_CHAR[c] = true;
        }
    }

    /**
     * Validates that the supplied string consists solely of characters
     * permitted in an HTTP token.  Returns {@code false} for {@code null},
     * empty strings, non‑ASCII characters, control characters, whitespace,
     * or any character not present in the token character set.
     *
     * @param str the string to validate
     * @return {@code true} if the string is a valid token, {@code false} otherwise
     */
    protected static boolean isValid(String str) {
        if (str == null || str.isEmpty()) {
            return false;
        }
        for (int i = 0; i < str.length(); i++) {
            char ch = str.charAt(i);
            // Reject any non‑ASCII character (including Unicode) and control chars
            if (ch >= TOKEN_CHAR.length || !TOKEN_CHAR[ch]) {
                return false;
            }
        }
        return true;
    }

