 * {@link CoderResult#isMalformed() malformed} results because the position of
 * the input {@link CharBuffer} was never advanced.  The new implementation
 * advances the buffer position for every error character and limits the
 * number of consecutive error‑handling iterations.  It also grows the output
 * buffer only when necessary and uses {@link CharsetEncoder#flush(ByteBuffer)}
 * to complete the encoding.</p>
 */
class NioZipEncoding implements ZipEncoding, CharsetAccessor {

    // -----------------------------------------------------------------------
    // other methods (unchanged)
    // -----------------------------------------------------------------------

    @Override
    public ByteBuffer encode(final String name) {
        final CharsetEncoder enc = newEncoder();
        final CharBuffer cb = CharBuffer.wrap(name);

        // Initial output buffer – size is an estimate based on the remaining chars.
        ByteBuffer out = ByteBuffer.allocate(estimateInitialBufferSize(enc, cb.remaining()));

        // Temporary buffer used when we have to encode a surrogate representation.
        CharBuffer surrogateTmp = CharBuffer.allocate(6);

        // Guard against pathological inputs that could otherwise cause an endless
        // loop – after a reasonable number of error‑handling iterations we abort.
        final int MAX_ERROR_ITERATIONS = 1024;
        int errorIterations = 0;

        while (true) {
            CoderResult res = enc.encode(cb, out, false);

            // -------------------------------------------------------------------
            // Normal termination – all input has been consumed.
            // -------------------------------------------------------------------
            if (res.isUnderflow()) {
                break;
            }

            // -------------------------------------------------------------------
            // Output buffer overflow – grow it and retry.
            // -------------------------------------------------------------------
            if (res.isOverflow()) {
                int increment = estimateIncrementalEncodingSize(enc, cb.remaining());
                out = ZipEncodingHelper.growBufferBy(out, increment);
                continue;
            }

            // -------------------------------------------------------------------
            // Error handling (malformed or unmappable input).
            // -------------------------------------------------------------------
            if (res.isMalformed() || res.isUnmappable()) {
                // Defensive: if the encoder reports an error length of zero we break
                // to avoid a tight infinite loop.
                if (res.length() == 0) {
                    break;
                }

