        // If the caller already supplied a Locale we trust it – it is an internal
        // object, not user‑controlled text.
        if (requestedLocale instanceof Locale) {
            Locale locale = (Locale) requestedLocale;
            LOG.debug("Applied request locale (already a Locale): {}", locale);
            return locale;
        }

        // Convert to String, trim whitespace and reject empty values.
        String localeStr = requestedLocale.toString().trim();
        if (localeStr.isEmpty()) {
            LOG.warn("Requested locale parameter is empty after trimming.");
            return null;
        }

        // Validate against the whitelist pattern.
