        String country = "";
        String variant = "";

        if (parts.length > 1) {
            country = parts[1];
        }
        if (parts.length > 2) {
            variant = parts[2];
        }

        Locale locale = new Locale(language, country, variant);
        LOG.debug("Applied request locale (validated): {}", locale);
