    /**
     * Creates an {@link LdapContext} that authenticates the supplied {@code principal}
     * and {@code credentials} over a STARTTLS protected connection.
     *
     * <p>The method follows the recommended pattern:
     * <ol>
     *   <li>Establish an unauthenticated LDAP connection.</li>
     *   <li>Upgrade the connection to TLS using STARTTLS.</li>
     *   <li>Bind with the supplied credentials over the encrypted channel.</li>
     * </ol>
     *
     * <p>Credentials are never sent in clear text and are not logged.  Any failure
     * during TLS negotiation or authentication results in the context being closed
     * and the exception being propagated.
     *
     * @param ldapContextFactory the factory that provides LDAP connection settings
     * @param principal the LDAP bind DN (must not be {@code null})
     * @param credentials the LDAP password (must not be {@code null})
     * @return a bound {@link LdapContext} ready for use
     * @throws NamingException if the bind fails or the server cannot be contacted
     */
    private LdapContext getLdapContextUsingStartTls(LdapContextFactory ldapContextFactory,
                                                   Object principal,
                                                   Object credentials) throws NamingException {
        if (principal == null) {
            throw new IllegalArgumentException("principal must not be null");
        }
        if (credentials == null) {
            throw new IllegalArgumentException("credentials must not be null");
        }

        JndiLdapContextFactory jndiLdapContextFactory = (JndiLdapContextFactory) ldapContextFactory;

        // Build the environment without any security credentials – they will be added
        // after the TLS channel has been established.
        Hashtable<String, Object> env = new Hashtable<>();
        env.put(Context.INITIAL_CONTEXT_FACTORY, jndiLdapContextFactory.getContextFactoryClassName());
        env.put(Context.PROVIDER_URL, jndiLdapContextFactory.getUrl());

        LdapContext ctx = null;
        try {
            // 1. Create an unauthenticated context.
            ctx = new InitialLdapContext(env, null);

            // 2. Upgrade the connection to TLS.
            StartTlsResponse tls = (StartTlsResponse) ctx.extendedOperation(new StartTlsRequest());
            try {
                tls.negotiate(); // performs the TLS handshake
            } catch (IOException e) {
                securityLog.error(withRealm(
                        "Failed to negotiate TLS connection with '%s': %s",
                        server(jndiLdapContextFactory), e.getMessage()));
                throw new CommunicationException(e.getMessage(), e);
            }

            // 3. Bind using the supplied credentials over the encrypted channel.
            ctx.addToEnvironment(Context.SECURITY_AUTHENTICATION,
                                 jndiLdapContextFactory.getAuthenticationMechanism());
            ctx.addToEnvironment(Context.SECURITY_PRINCIPAL, principal);
            ctx.addToEnvironment(Context.SECURITY_CREDENTIALS, credentials);

            // Force a re‑bind so that the credentials are applied now that the channel is encrypted.
            ctx.reconnect(null);

            return ctx; // caller is responsible for closing the context
        } catch (NamingException e) {
            // Authentication or other LDAP error – ensure resources are released.
            securityLog.error(withRealm(
                    "LDAP authentication failed for user '%s' on server '%s': %s",
                    principal, server(jndiLdapContextFactory), e.getMessage()));
            LdapUtils.closeContext(ctx);
            throw e;
        } catch (RuntimeException e) {
            // Any unexpected runtime exception – also clean up.
            LdapUtils.closeContext(ctx);
            throw e;
        }
    }
