/**
 * Implementation of read for STORED entries.
 *
 * This method has been hardened against crafted ZIP archives that
 * provide an incorrect uncompressed size.  The original implementation
 * relied solely on {@code current.bytesRead >= csize} to signal EOF.
 * If the declared size is larger than the actual data, the method could
 * keep attempting to read from the underlying stream indefinitely.
 *
 * The new implementation adds several safety checks:
 * <ul>
 *   <li>Validate that the entry size is non‑negative.  A negative size is
 *       treated as an unexpected condition and results in an {@link IOException}.</li>
 *   <li>Detect premature EOF from the underlying stream even when the
 *       declared size has not been reached.</li>
 *   <li>Guarantee that a non‑positive {@code toRead} value results in {@code -1},
 *       preventing an infinite loop.</li>
 *   <li>Guard against integer overflow when converting the remaining
 *       size to an {@code int}.</li>
 * </ul>
 *
 * These measures ensure that the method always terminates correctly,
 * eliminating the infinite‑stream vulnerability.
 */
private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
    // If the entry uses a data descriptor we have already cached the whole
    // entry in {@code lastStoredEntry}.
    if (current.hasDataDescriptor) {
        if (lastStoredEntry == null) {
            readStoredEntry();               // cache the entry
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    // -----------------------------------------------------------------
    // 1. Validate the declared size of the entry.
    // -----------------------------------------------------------------
    final long csize = current.entry.getSize();
    if (csize < 0) {
        // According to the ZIP spec a STORED entry must have a known size.
        // A negative size indicates a malformed archive.
        throw new IOException("Invalid stored entry size: " + csize);
    }

    // -----------------------------------------------------------------
    // 2. Normal EOF detection based on the declared size.
    // -----------------------------------------------------------------
    if (current.bytesRead >= csize) {
        return -1; // reached the end of the entry as declared
    }

    // -----------------------------------------------------------------
    // 3. Fill the internal buffer if it is exhausted.
    // -----------------------------------------------------------------
    if (buf.position() >= buf.limit()) {
        buf.position(0);
        final int l = in.read(buf.array());
        if (l == -1) {
            // Underlying stream ended before the declared size was reached.
            // Treat this as EOF for the entry.
            return -1;
        }
        buf.limit(l);
        count(l);
        current.bytesReadFromStream += l;
    }

    // -----------------------------------------------------------------
    // 4. Determine the safe number of bytes to return.
    // -----------------------------------------------------------------
    int toRead = Math.min(buf.remaining(), length);
    long remainingInEntry = csize - current.bytesRead;
    if (remainingInEntry < toRead) {
        // Guard against overflow and ensure we never read past the entry.
        toRead = (int) remainingInEntry;
    }

    // If, for any reason, no bytes can be read, signal EOF.
    if (toRead <= 0) {
        return -1;
    }

    // -----------------------------------------------------------------
    // 5. Transfer data to the caller's buffer.
    // -----------------------------------------------------------------
    buf.get(buffer, offset, toRead);
    current.bytesRead += toRead;
    return toRead;
}
