import java.util.Calendar;
import static java.util.Calendar.*;

public final class CronTab {

    // other methods ...

    /**
     * See {@link #ceil(long)}.
     *
     * This method modifies the given calendar and returns the same object.
     *
     * @throws RareOrImpossibleDateException if the date isn't hit in the 2 years after it indicates an impossible
     * (e.g. Jun 31) date, or at least a date too rare to be useful. This addresses JENKINS-41864 and was added in 2.49
     */
    public Calendar ceil(Calendar cal) {
        // Clone the input calendar to obtain an upper bound (two years in the future).
        Calendar twoYearsFuture = (Calendar) cal.clone();
        twoYearsFuture.add(Calendar.YEAR, 2);

        // Defensive guard – we do not want the algorithm to spin forever.
        // The theoretical maximum number of adjustments is bounded by the product of the
        // field cardinalities, but a conservative hard‑limit is sufficient and inexpensive.
        final int MAX_ITERATIONS = 1_000;          // safe upper‑bound for production use
        int iterationCount = 0;

        // Keep a snapshot of the calendar state from the previous outer iteration.
        // This allows us to detect a situation where the algorithm makes no forward progress.
        Calendar previousIteration = (Calendar) cal.clone();

        OUTER:
        while (true) {
            // -----------------------------------------------------------------
            // 1.  Prevent pathological infinite loops.
            // -----------------------------------------------------------------
            if (++iterationCount > MAX_ITERATIONS) {
                throw new RareOrImpossibleDateException(
                        "Ceiling calculation exceeded safe iteration limit (" + MAX_ITERATIONS + ").");
            }

            // If the calendar has moved backwards or stayed the same since the last
            // outer iteration, we are stuck in a loop – abort with a clear exception.
            if (cal.compareTo(previousIteration) <= 0) {
                throw new RareOrImpossibleDateException(
                        "Ceiling calculation made no forward progress; possible infinite loop.");
            }
            // Remember the current state for the next iteration's progress check.
            previousIteration = (Calendar) cal.clone();

            // -----------------------------------------------------------------
            // 2.  Abort if we have passed the two‑year safety window.
            // -----------------------------------------------------------------
            if (cal.compareTo(twoYearsFuture) > 0) {
                throw new RareOrImpossibleDateException();
            }

            // -----------------------------------------------------------------
            // 3.  Walk through the fields in the defined adjustment order.
            // -----------------------------------------------------------------
            for (CalendarField f : CalendarField.ADJUST_ORDER) {

                int cur = f.valueOf(cal);
                int next = f.ceil(this, cur);

                // No change required for this field – move to the next one.
                if (cur == next) {
                    continue;
                }

                // Reset all less‑significant fields because a higher‑order field is about
                // to change. This mirrors the behaviour of traditional cron implementations.
                for (CalendarField l = f.lowerField; l != null; l = l.lowerField) {
                    l.clear(cal);
                }

                // -----------------------------------------------------------------
                // 4.  Handle the situation where the field has no valid value (next < 0).
                // -----------------------------------------------------------------
                if (next < 0) {
                    // Roll the current field up by one step and set it to the first valid value.
                    // After this adjustment we must restart the whole process because higher
                    // fields may now be out of sync.
                    f.rollUp(cal, 1);
                    f.setTo(cal, f.first(this));
                    // Update the snapshot before looping again so the progress check works.
                    previousIteration = (Calendar) cal.clone();
                    continue OUTER;
                } else {
                    // Normal case – set the field to the computed next value.
                    f.setTo(cal, next);

                    // Some fields (e.g., day‑of‑month) may require a full re‑evaluation after
                    // being modified because they affect other fields.
                    if (f.redoAdjustmentIfModified) {
                        // Update the snapshot before restarting.
                        previousIteration = (Calendar) cal.clone();
                        continue OUTER;
                    }
                }
            }

            // -----------------------------------------------------------------
            // 5.  All fields are now consistent – return the adjusted calendar.
            // -----------------------------------------------------------------
            return cal;
        }
    }

    // other methods ...

}
