    /**
     * Creates a {@link SAXSource} from a {@link StreamSource} while protecting against
     * XXE attacks. The method disables DTD processing and external entity resolution
     * on the underlying parser.
     *
     * @param source   the incoming XML source; must not be {@code null}
     * @param exchange the Camel exchange (may be {@code null}); if it contains a
     *                 {@link SAXParserFactory} it will be reused after being hardened
     * @return a {@link SAXSource} ready for further processing
     * @throws SAXException if a secure parser cannot be created
     */
    @Converter
    public SAXSource toSAXSourceFromStream(StreamSource source, Exchange exchange) throws SAXException {
        if (source == null) {
            throw new IllegalArgumentException("StreamSource must not be null");
        }

        // ---------------------------------------------------------------------
        // Build the InputSource – prefer a Reader, fall back to InputStream,
        // otherwise rely on the systemId (if any). If none are available we fail.
        // ---------------------------------------------------------------------
        InputSource inputSource;
        if (source.getReader() != null) {
            inputSource = new InputSource(source.getReader());
        } else if (source.getInputStream() != null) {
            inputSource = new InputSource(source.getInputStream());
        } else if (source.getSystemId() != null) {
            inputSource = new InputSource(source.getSystemId());
        } else {
            throw new IllegalArgumentException("StreamSource does not contain a Reader, InputStream or SystemId");
        }
        inputSource.setSystemId(source.getSystemId());
        inputSource.setPublicId(source.getPublicId());

        // ---------------------------------------------------------------------
        // Obtain (or create) a SAXParserFactory and harden it against XXE.
        // ---------------------------------------------------------------------
        SAXParserFactory factory = null;
        if (exchange != null) {
            factory = exchange.getProperty(Exchange.SAXPARSER_FACTORY, SAXParserFactory.class);
        }
        if (factory == null) {
            factory = SAXParserFactory.newInstance();
        }

        try {
            // General hardening
            factory.setNamespaceAware(true);
            factory.setXIncludeAware(false);
            factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
            // Disable DTDs entirely
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            // Disable external entities
            factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
            factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            // Prevent loading of external DTDs/grammars
            factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            factory.setFeature("http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);
        } catch (ParserConfigurationException | SAXException e) {
            // If the underlying parser does not support a feature we log and continue;
            // the most critical ones (disallow-doctype-decl) have already been set.
            LOG.warn("Unable to set a secure feature on SAXParserFactory: {}", e.getMessage());
        }

        // ---------------------------------------------------------------------
        // Create the XMLReader and apply the same hardening at the reader level.
        // ---------------------------------------------------------------------
        XMLReader xmlReader;
        try {
            SAXParser parser = factory.newSAXParser();
            xmlReader = parser.getXMLReader();

            // The same set of protections on the XMLReader (some parsers require it here)
            xmlReader.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            xmlReader.setFeature("http://xml.org/sax/features/external-general-entities", false);
            xmlReader.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            xmlReader.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            xmlReader.setFeature("http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);
        } catch (Exception e) {
            // Any failure to obtain a secure XMLReader is considered fatal.
            LOG.warn("Cannot create a secure SAX XMLReader, due to {}", e.toString());
            throw new SAXException("Failed to create a secure XMLReader", e);
        }

        return new SAXSource(xmlReader, inputSource);
    }

    // -------------------------------------------------------------------------
    // Other conversion utilities (omitted for brevity)
    // -------------------------------------------------------------------------
}
