    /**
     * Determines whether the incoming request is allowed to modify the SCIM user identified
     * by the path variable.
     *
     * @param request the HTTP request containing the JSON payload and authentication information
     * @return {@code true} if the request is authorized, {@code false} otherwise
     * @throws IOException if the request body cannot be read
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

