        try {
            scimUserFromDb = scimUserProvisioning.retrieve(targetUserId, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist we cannot enforce ownership – keep original semantics.
            return true;
        }

        // 4️⃣  Ownership / admin check.
        boolean isAdmin = isAdmin(request);
        if (!isAdmin && !authenticatedUserId.equals(scimUserFromDb.getId())) {
            // Non‑admin users may only modify their own record.
            return false;
        }

        // 5️⃣  Parse the incoming JSON payload safely.
        String requestBody = IOUtils.toString(request.getReader());
        if (requestBody == null || requestBody.trim().isEmpty()) {
            // Empty payload – nothing to validate, deny to avoid accidental overwrites.
            return false;
        }

        ScimUser scimUserFromRequest;
        try {
            scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);
        } catch (Exception e) {
            // Malformed JSON – reject the request.
            return false;
        }

        // 6️⃣  Field‑level validation.
        // Non‑admin users must not change immutable fields.
        if (!isAdmin) {
            if (!equalsSafe(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
